pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;
    let density = item_size as f64 / bin_capacity as f64;

    // Base score: prefer lower residual after placement
    let mut score = residual_ratio * (1.0 + 1.5 * t);

    // Tight‑fit bonus: small gap after placing the item
    if bin_residual >= item_size {
        let gap_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= (-gap_ratio * gap_ratio / 0.004).exp();
    }

    // Align with mean residual
    let diff = (residual_ratio - mean_ratio).abs();
    score -= (-diff * diff / 0.008).exp();

    // Look‑ahead: prefer bins that can still hold the next item
    if next_item_size > 0 {
        let next_ratio = next_item_size as f64 / bin_capacity as f64;
        if post_residual >= next_item_size {
            score -= next_ratio * 3.8 * (1.0 - t).sqrt();
        } else {
            score += next_ratio * 2.9 * (1.0 - t).sqrt();
        }
    }

    // Fewer fitting bins is better
    score += 3.2 / ((fitting_bins_count as f64 + 1.0).ln().max(1.0));

    // Penalise when many bins are open
    score += (open_bins_count as f64).ln() * 0.04 * (1.0 - t);
    score += (open_bins_count as f64).powf(1.3) * 0.015 * (1.0 - t);

    // New‑bin handling
    if bin_residual == bin_capacity {
        // Early reward for opening a new bin
        score -= 0.55 * (1.0 - t) + 0.18 * (1.0 - t).powi(2);
    } else {
        // Slight penalty for using an existing bin when many are open
        score += (open_bins_count as f64).ln() * 0.03 * (1.0 - t);
    }

    // Extremes of residual ratio
    if residual_ratio < 0.05 {
        score -= 0.35;
    } else if residual_ratio > 0.90 {
        score += 0.22;
    }

    // Additional penalty for large deviation from mean residual
    if diff > 0.12 {
        score += (diff - 0.12).powi(2) * 4.5;
    }

    // Density penalty: avoid packing tiny items into huge bins
    if density < 0.08 {
        score += (0.08 - density).powi(2) * 2.8;
    }

    // Minor penalty when residual is high and next item is large
    if residual_ratio > 0.65 && next_item_size > bin_capacity / 3 {
        score += 0.12 * residual_ratio;
    }

    score
