    // Non‑linear penalty for large residuals (softened exponent)
    score += residual_ratio.powf(1.2) * 4.0 * (1.0 - t);

    // Gaussian penalty around the mean residual ratio
    let mean_ratio = mean_residual / bin_capacity as f64;
    let diff = (residual_ratio - mean_ratio).abs();
    score -= (-diff * diff / 0.025).exp();

    // Extra penalty if residual exceeds mean by more than 5%
    if residual_ratio > mean_ratio + 0.05 {
        score += (residual_ratio - mean_ratio - 0.05) * 3.0 * (1.0 - t);
    }

    // Dead‑space penalty: discourage bins with too much free space
    let dead_space_ratio = 1.0 - residual_ratio;
    if dead_space_ratio > 0.4 {
        score += dead_space_ratio * 5.0 * (1.0 - t);
        if dead_space_ratio > 0.6 {
            score += 2.0 * dead_space_ratio * (1.0 - t);
        }
    }

    // Look‑ahead for the next item
    if next_item_size > 0 {
        let next_ratio = next_item_size as f64 / bin_capacity as f64;
        if post_residual >= next_item_size {
            // Residual after placing the next item
            let next_post_ratio =
                (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= (1.0 - next_post_ratio) * 8.0 * (1.0 - t).powf(0.8);
