        / ((fitting_bins_count as f64 + 1.0).ln().max(1.0));

    // Special handling for a brand‑new empty bin
    if bin_residual == bin_capacity {
        score -= 0.4 * (1.0 - t);
    } else {
        // Penalise using an existing bin when many are already open
        score += (open_bins_count as f64).ln() * 0.05 * (1.0 - t);
    }

    // Additional penalty for having many open bins
    score += (open_bins_count as f64).powi(2) * 0.008 * (1.0 - t);

